$('analyzeAiFood')?.addEventListener('click',async()=>{if(!aiFoodPhotoData)return;const btn=$('analyzeAiFood');btn.disabled=true;$('aiFoodStatus').textContent='جاري تحليل الصورة…';try{throw new Error('تحليل الصور يحتاج خدمة إنترنت غير موجودة في النسخة الشخصية. أضف الأصناف يدويًا.');const rawFoods=[];const arr=rawFoods.map(x=>({name:x.name,grams:x.grams??x.quantity??100,kcal:x.kcal??x.calories??0,protein:x.protein??0,carbs:x.carbs??0,fat:x.fat??0}));if(!arr.length)throw new Error('لم أتعرف على أصناف واضحة. جرّب صورة أوضح أو أضف الأصناف يدويًا.');aiFoodDraft=arr.map(x=>({name:String(x.name||'صنف غير معروف').slice(0,100),grams:Math.max(1,aiNum(x.grams)||100),kcal:aiNum(x.kcal),protein:aiNum(x.protein),carbs:aiNum(x.carbs),fat:aiNum(x.fat)}));renderAiFoodDraft();syncAiTotals();$('aiFoodEditor').classList.remove('hidden');$('aiFoodStatus').textContent=(data.note||data.notes||'تقدير تقريبي من الصورة. عدّل الكميات والقيم حسب وجبتك.');}catch(err){console.error('AI food analysis failed',err);$('aiFoodStatus').textContent='التحليل بالـ AI مش متصل أو حصل خطأ. راجع إعداد Supabase Edge Function في ملف AI_FOOD_SETUP_AR.md. تقدر تضيف الأصناف يدويًا.';$('aiFoodEditor').classList.remove('hidden');if(!aiFoodDraft.length){aiFoodDraft=[{name:'صنف 1',grams:100,kcal:0,protein:0,carbs:0,fat:0}];renderAiFoodDraft();syncAiTotals()}}finally{btn.disabled=false}});
