$('saveAiFood')?.addEventListener('click',()=>{if(!aiFoodDraft.length){showFoodToast('أضف صنفًا واحدًا على الأقل');return}const valid=aiFoodDraft.filter(x=>String(x.name||'').trim());if(!valid.length){showFoodToast('اكتب اسم صنف واحد على الأقل');return}const totals=aiTotals(),target={kcal:aiNum($('aiTotalKcal').value),protein:aiNum($('aiTotalProtein').value),carbs:aiNum($('aiTotalCarbs').value),fat:aiNum($('aiTotalFat').value)};const scale=(key)=>totals[key]>0?target[key]/totals[key]:1;const meal=$('aiMealType').value,now=Date.now();valid.forEach((x,i)=>{const factor=aiNum(x.grams)/Math.max(1,aiNum(x.grams));db.logs.push({type:'food',who:current,title:String(x.name).trim(),meal,grams:aiNum(x.grams)||100,count:1,kcal:Math.round(target.kcal!==totals.kcal?aiNum(x.kcal)*scale('kcal'):aiNum(x.kcal)),protein:+(target.protein!==totals.protein?aiNum(x.protein)*scale('protein'):aiNum(x.protein)).toFixed(1),carbs:+(target.carbs!==totals.carbs?aiNum(x.carbs)*scale('carbs'):aiNum(x.carbs)).toFixed(1),fat:+(target.fat!==totals.fat?aiNum(x.fat)*scale('fat'):aiNum(x.fat)).toFixed(1),fiber:0,id:now+i+Math.random(),createdAt:now,date:today(),source:'ai-photo'});});addPoints(current,2);save();renderAll();closeAiFood();showSuccessPulse('اتسجلت وجبتك بنجاح',`تم تسجيل ${valid.length} أصناف في يومك`);aiFoodDraft=[];aiFoodPhotoData=null;$('aiFoodImage').value='';$('aiFoodPreview').classList.add('hidden');$('aiFoodEditor').classList.add('hidden')});


function showSuccessPulse(title,subtitle='تم تحديث يومك'){let el=$('successPulse');if(!el){el=document.createElement('div');el.id='successPulse';el.className='success-pulse';el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.innerHTML='<div class="success-pulse-card"><div class="success-check-wrap"><svg viewBox="0 0 52 52" aria-hidden="true"><circle class="success-check-circle" cx="26" cy="26" r="23"/><path class="success-check-mark" d="M14 27l8 8 16-18"/></svg></div><strong class="success-title"></strong><span class="success-subtitle"></span></div>';document.body.appendChild(el)}el.querySelector('.success-title').textContent=title;el.querySelector('.success-subtitle').textContent=subtitle;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');clearTimeout(window.__successPulseTimer);window.__successPulseTimer=setTimeout(()=>el.classList.remove('show'),1750)}
function showFoodToast(message){let t=$('foodToast');if(!t){t=document.createElement('div');t.id='foodToast';t.className='food-toast';t.setAttribute('role','status');document.body.appendChild(t)}t.textContent=message;t.classList.add('show');clearTimeout(window.__foodToastTimer);window.__foodToastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
function renderList(id,items,formatter,empty='لسه مفيش تسجيلات.'){let sorted=[...items].sort((a,b)=>(b.date||'').localeCompare(a.date||''));$(id).innerHTML=sorted.length?sorted.map(x=>`<div class="log-item"><div><strong>${x.title}</strong><small>${NAMES[x.who]||x.who} · ${prettyDate(x.date)}${x.meal?' · '+x.meal:''}</small></div><div class="log-right">${formatter(x)}${id==='foodLog'&&x.who===current?`<div class="food-log-actions"><button type="button" class="secondary compact" data-edit-meal="${x.id}">تعديل</button><button type="button" class="secondary compact danger-action" data-delete-meal="${x.id}">حذف</button></div>`:''}${['activityLog','activityHistoryLog'].includes(id)&&x.who===current?`<div class="food-log-actions"><button type="button" class="secondary compact danger-action" data-delete-activity="${x.id}">حذف النشاط</button></div>`:''}</div></div>`).join(''):`<p class="muted">${empty}</p>`;if(id==='foodLog'){ $(id).querySelectorAll('[data-delete-meal]').forEach(b=>b.onclick=()=>{const entry=db.logs.find(x=>String(x.id)===b.dataset.deleteMeal&&x.type==='food'&&x.who===current);if(!entry)return;if(!confirm(`تحذف وجبة «${entry.title}»؟`))return;const deletedId=String(entry.id);db.logs=db.logs.filter(x=>String(x.id)!==deletedId);db.deletedLogIds=[...new Set([...(db.deletedLogIds||[]).map(String),deletedId])];sharedState.deletedLogIds=[...new Set([...(sharedState.deletedLogIds||[]).map(String),deletedId])];sharedState.logs=(sharedState.logs||[]).filter(x=>String(x.id)!==deletedId);localSave();save();renderAll();persistRemote().then(()=>showFoodToast('✓ تم حذف الوجبة نهائيًا وتحديث السعرات')).catch(err=>{console.error('Food deletion sync failed:',err);showFoodToast('اتحذفت من الجهاز، لكن مزامنة الحذف فشلت؛ سيُعاد المحاولة عند الاتصال')})});$(id).querySelectorAll('[data-edit-meal]').forEach(b=>b.onclick=()=>{const entry=db.logs.find(x=>String(x.id)===b.dataset.editMeal&&x.type==='food'&&x.who===current);if(!entry)return;const grams=prompt('عدّل الكمية بالجرام/مل:',String(entry.grams||100));if(grams===null)return;const g=Number(grams);if(!Number.isFinite(g)||g<=0){showFoodToast('اكتب كمية صحيحة أكبر من صفر');return}const old=Math.max(0.001,Number(entry.grams)||100),ratio=g/old;const meal=prompt('نوع الوجبة (فطار، غداء، عشاء، سناك، مشروب):',entry.meal||'سناك');if(meal===null)return;entry.grams=Math.round(g*10)/10;entry.kcal=Math.round((+entry.kcal||0)*ratio);['protein','carbs','fat','fiber'].forEach(k=>entry[k]=+((+entry[k]||0)*ratio).toFixed(1));entry.meal=meal.trim()||entry.meal;entry.updatedAt=Date.now();save();renderAll();showFoodToast('✓ تم تعديل الوجبة وتحديث القيم الغذائية')});}if(['activityLog','activityHistoryLog'].includes(id)){ $(id).querySelectorAll('[data-delete-activity]').forEach(b=>b.onclick=()=>{const entry=db.logs.find(x=>String(x.id)===b.dataset.deleteActivity&&['run','walk','exercise','workout'].includes(x.type)&&x.who===current);if(!entry)return;if(!confirm(`تحذف نشاط «${entry.title|| (entry.type==='walk'?'مشي':entry.type==='run'?'جري':'تمرين')}» من سجلك؟`))return;db.logs=db.logs.filter(x=>x!==entry);db.deletedLogIds=[...new Set([...(db.deletedLogIds||[]).map(String),String(entry.id)])];sharedState.deletedLogIds=[...new Set([...(sharedState.deletedLogIds||[]).map(String),String(entry.id)])];sharedState.logs=(sharedState.logs||[]).filter(x=>String(x.id)!==String(entry.id));save();renderAll();persistRemote().catch(err=>{console.error('Activity deletion sync failed:',err);showFoodToast('اتحذف من الجهاز، لكن المزامنة فشلت؛ تحقق من الاتصال')});showFoodToast('✓ تم حذف النشاط من السجل')});}}
function personCard(who){let runs=sumRun(who),walks=sumWalk(who),ex=ownLogs(who).filter(x=>['run','exercise','workout','walk'].includes(x.type)).length;return `<article class="person-card ${who===current?'me-card':''}"><h3>${who===current?'⭐ ':''}${NAMES[who]}</h3><div class="mini"><span>إجمالي الجري</span><b>${num(runs,2)} كم</b></div><div class="mini"><span>إجمالي المشي</span><b>${num(walks,2)} كم</b></div><div class="mini"><span>الأنشطة</span><b>${ex}</b></div></article>`}
function renderRunHistory(){let chosen=$('runHistoryDate')?.value||'';let runs=db.logs.filter(x=>x.type==='run'&&(!chosen||x.date===chosen));if($('runHistoryCaption'))$('runHistoryCaption').textContent=chosen?`جريات يوم ${prettyDate(chosen)}`:`كل الجريات المسجلة، مرتبة من الأحدث للأقدم`;renderList('runHistory',runs,x=>`<b>${num(x.km,2)} كم</b><br><small>${x.min||'—'} دقيقة${x.pace?' · بيس '+x.pace:''}</small>`,'مفيش جريات في التاريخ ده.');}
