function compareIcon(kind){const paths={ruler:'<path d="M4 16 16 4l4 4L8 20z"/><path d="m12 8 2 2m-5 1 2 2m-5 1 2 2"/>',weight:'<path d="M6 7h12l2 13H4z"/><path d="M9 7a3 3 0 0 1 6 0"/>',calories:'<path d="M12 22c4 0 7-3 7-7 0-3-2-5-4-7 0 3-2 4-2 4 0-4-2-7-5-10 1 5-4 8-4 13 0 4 3 7 8 7Z"/><path d="M12 22c-2 0-3-2-3-4 0-2 2-3 3-5 2 2 3 3 3 5 0 2-1 4-3 4Z"/>',water:'<path d="M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12Z"/><path d="M9 16a3 3 0 0 0 3 3"/>',sleep:'<path d="M19 15A8 8 0 0 1 9 5a8 8 0 1 0 10 10Z"/><path d="M16 4v4m-2-2h4"/>'};return `<svg class="compare-icon-svg icon-${kind}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" role="img" aria-label="${kind}" style="display:block;width:24px;height:24px;min-width:24px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round">${paths[kind]||''}</svg>`}
function compareNeedCard(who){const p=getProfile(who);const logs=ownLogs(who).filter(x=>x.date===today());const eaten=logs.filter(x=>x.type==='food').reduce((s,x)=>s+(+x.kcal||0),0);const water=logs.filter(x=>x.type==='water').reduce((s,x)=>s+(Number(x.ml)||0),0);const sleep=ownLogs(who,'sleep').filter(x=>x.date===today()).sort((a,b)=>(Number(b.createdAt)||Number(b.id)||0)-(Number(a.createdAt)||Number(a.id)||0))[0];const slept=sleep?Math.max(0,+sleep.hours||0):0;const calGoal=p?p.calories:0,waterGoal=p?p.water:0,sleepGoal=8;const remainCal=Math.max(0,calGoal-eaten),remainWater=Math.max(0,waterGoal-water),remainSleep=Math.max(0,sleepGoal-slept);const pct=(a,b)=>b?Math.min(100,a/b*100):0;return `<article class="panel compare-needs-card ${who===current?'me-card':''}"><h3>${who===current?'⭐ ':''}${NAMES[who]}</h3>${p?`<div class="compare-body-stats"><span><i class="compare-body-icon ruler-icon">${compareIcon('ruler')}</i><span>الطول</span><b>${num(p.height)} سم</b></span><span><i class="compare-body-icon weight-icon">${compareIcon('weight')}</i><span>الوزن</span><b>${num(p.weight)} كجم</b></span></div><div class="compare-metric"><div class="compare-metric-head"><span class="compare-metric-label"><i class="compare-metric-icon calories-icon">${compareIcon('calories')}</i>السعرات</span><b>${num(eaten)} / ${num(calGoal)} سعرة</b></div><div class="progress"><span style="width:${pct(eaten,calGoal)}%"></span></div><small>المتبقي: ${num(remainCal)} سعرة${eaten>calGoal?' · تجاوزت الهدف بـ '+num(eaten-calGoal):''}</small></div><div class="compare-metric"><div class="compare-metric-head"><span class="compare-metric-label"><i class="compare-metric-icon water-icon">${compareIcon('water')}</i>المياه</span><b>${num(water)} / ${num(waterGoal)} مل</b></div><div class="progress water-progress"><span style="width:${pct(water,waterGoal)}%"></span></div><small>المتبقي: ${num(remainWater)} مل${water>waterGoal?' · تجاوزت الهدف بـ '+num(water-waterGoal)+' مل':''}</small></div>`:`<p class="muted">احتياج السعرات والمياه غير متاح. أكمل بيانات الجسم لهذا الحساب.</p>`}<div class="compare-metric"><div class="compare-metric-head"><span class="compare-metric-label"><i class="compare-metric-icon sleep-icon">${compareIcon('sleep')}</i>النوم</span><b>${num(slept,1)} / ${sleepGoal} ساعات</b></div><div class="progress sleep-progress"><span style="width:${pct(slept,sleepGoal)}%"></span></div><small>${sleep?'المتبقي للوصول إلى 8 ساعات: '+num(remainSleep,1)+' ساعة':'لم يتم تسجيل النوم اليوم · الهدف 8 ساعات'}</small></div></article>`}
function renderCompare(){const other=current==='Amr'?'Ziad':'Amr';const duoLabel=`أنا و${NAMES[other]}`;if($('compareNavLabel'))$('compareNavLabel').textContent=duoLabel;if($('comparePageTitle'))$('comparePageTitle').textContent=duoLabel;if($('homeCompareTitle'))$('homeCompareTitle').textContent=`${NAMES[current]} و${NAMES[other]}`;$('compareCards').innerHTML=PEOPLE.map(personCard).join('');$('homeCompare').innerHTML=PEOPLE.map(personCard).join('');if($('compareNeedsCards'))$('compareNeedsCards').innerHTML=PEOPLE.map(compareNeedCard).join('');let max=Math.max(1,...PEOPLE.map(sumRun));$('runCompare').innerHTML=PEOPLE.map(p=>{let km=sumRun(p);return `<div class="barrow"><b>${NAMES[p]}</b><div class="bar"><span style="width:${km/max*100}%"></span></div><strong>${num(km,2)} كم</strong></div>`}).join('');if($('walkCompare'))$('walkCompare').innerHTML=PEOPLE.map(p=>{let km=sumWalk(p),maxWalk=Math.max(1,...PEOPLE.map(sumWalk));return `<div class="barrow"><b>${NAMES[p]}</b><div class="bar"><span style="width:${km/maxWalk*100}%;background:linear-gradient(90deg,#39c7ff,#70e0b0)"></span></div><strong>${num(km,2)} كم</strong></div>`}).join('');renderRunHistory();renderList('teamActivity',db.logs.filter(x=>['run','walk','exercise','workout'].includes(x.type)),x=>x.type==='run'?`<b>🏃 جري · ${num(x.km,2)} كم</b><br><small>${num(x.min)} دقيقة · بيس ${num(x.pace||((+x.min||0)/(+x.km||1)),2)} دقيقة/كم</small>`:x.type==='walk'?`<b>🚶 مشي</b><br><small>${x.steps?num(x.steps)+' خطوة · ':''}${num(x.km,2)} كم · ${num(x.min)} دقيقة</small>`:x.type==='workout'?`<b>💪 ${x.title}</b><br><small>${x.sets||0} مجموعات × ${x.reps||'—'} عدة</small>`:`<b>🏋️ نشاط · ${x.title||'تمرين'}</b><br><small>${num(x.min)} دقيقة</small>`,'مفيش أنشطة رياضية مسجلة.')}
