  let entries=Object.entries(EXERCISES).filter(([key,ex])=>{
   if(!q)return true;
   const hay=normSearch(key+' '+ex.name);return terms.some(t=>t&&hay.includes(t))||q.split(/[\s,]+/).filter(Boolean).every(t=>hay.includes(t));
  });
