function renderMuscleRecovery(){if(!$('muscleRecovery'))return;const keys=Object.keys(MUSCLES);$('muscleRecovery').innerHTML='<p class="muted tiny sleep-recovery-note">النوم المسجّل بعد التمرين قد يحسّن تقدير الاستشفاء بشكل محدود؛ 7–9 ساعات تعطي أفضل دعم في الحساب. النسبة تقديرية وليست قياسًا طبيًا.</p>'+keys.map(m=>{const recovery=muscleRecovery(m);return `<div class="recovery-item" id="recovery-${m}" data-recovery-muscle="${m}"><div class="recovery-head"><b>${MUSCLES[m]}</b><span>${recovery}% تعافٍ</span></div><div class="progress"><span style="width:${recovery}%;background:${recovery<40?'#ff5a00':recovery<75?'#ff8a38':recovery>=98?'#22c55e':'#a3b18a'}"></span></div><small>${recovery<40?'إجهاد مرتفع نسبيًا — الراحة قد تفيد':recovery<75?'تعافٍ مستمر':'جاهزية تقديرية أعلى'}</small></div>`}).join('');document.querySelectorAll('.muscle-zone').forEach(el=>{const r=muscleRecovery(el.dataset.muscle);el.style.fill=r>=98?'rgba(34,197,94,.24)':r>=90?'rgba(132,204,22,.20)':`rgba(255,90,0,${Math.max(.08,(100-r)/100*.95)})`;el.style.stroke=r>=98?'#4ade80':r>=90?'#a3e635':'#ff873d';el.style.strokeWidth=r>=98?'1.8':'1';el.style.opacity=String(r>=98?1:Math.max(.48,(100-r)/100));el.setAttribute('tabindex','0');el.setAttribute('role','button');el.setAttribute('aria-label',`${MUSCLES[el.dataset.muscle]||'العضلة'} — اضغط لعرض نسبة التعافي`);el.setAttribute('title','اضغط لعرض نسبة التعافي')} )}
// Interactive muscle map: selecting a muscle takes the user to its matching recovery card.
if(!window.__fitbrosMuscleMapBound){window.__fitbrosMuscleMapBound=true;let muscleHighlightTimer=0;const clearMuscleHighlight=()=>document.querySelectorAll('.recovery-item.selected-muscle,.muscle-zone.selected-muscle').forEach(n=>n.classList.remove('selected-muscle'));const selectMuscle=el=>{const key=el?.dataset?.muscle;if(!key)return;const card=$('recovery-'+key);if(!card){const aliases={quads:'rectusFemoris',hamstrings:'bicepsFemoris',calves:'gastrocnemius',hipFlexors:'abs',obliques:'abs',lowerBack:'back'};const alt=aliases[key];if(alt&&$('recovery-'+alt))return selectMuscle({dataset:{muscle:alt}});return;}clearTimeout(muscleHighlightTimer);clearMuscleHighlight();card.classList.add('selected-muscle');document.querySelectorAll(`.muscle-zone[data-muscle="${key}"]`).forEach(n=>n.classList.add('selected-muscle'));card.scrollIntoView({behavior:'smooth',block:'center'});muscleHighlightTimer=setTimeout(clearMuscleHighlight,1400);};document.addEventListener('click',e=>{const zone=e.target.closest('.muscle-zone');if(zone){selectMuscle(zone);return;}if(!e.target.closest('.recovery-item'))clearMuscleHighlight();});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.classList?.contains('muscle-zone')){e.preventDefault();selectMuscle(e.target);}});document.addEventListener('click',e=>{const card=e.target.closest('[data-recovery-muscle]');if(card&&!e.target.closest('button'))selectMuscle({dataset:{muscle:card.dataset.recoveryMuscle}});});}
function renderDailyHistory(){
 const host=$("dailyHistoryList");if(!host)return;
 const logs=ownLogs(current);
 const dates=[...new Set(logs.filter(x=>["food","water","sleep"].includes(x.type)&&x.date).map(x=>x.date))].sort((a,b)=>b.localeCompare(a));
 if(!dates.length){host.innerHTML='<div class="panel muted">لسه مفيش أيام مسجلة لحسابك. أول ما تسجل أكل أو مياه أو نوم هيظهر هنا.</div>';return;}
 const safe=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 host.innerHTML=dates.map(date=>{
  const day=logs.filter(x=>x.date===date),food=day.filter(x=>x.type==='food');
  const kcal=food.reduce((s,x)=>s+(Number(x.kcal)||0),0),protein=food.reduce((s,x)=>s+(Number(x.protein)||0),0);
  const water=day.filter(x=>x.type==='water').reduce((s,x)=>s+(Number(x.ml)||0),0),sleep=day.filter(x=>x.type==='sleep').reduce((s,x)=>Math.max(s,Number(x.hours)||0),0);
  const foods=food.length?food.map(x=>`<div class="history-food-row"><span><strong>${safe(x.title||'صنف')}</strong><small class="muted">${safe(x.meal||'وجبة')} · ${num(Number(x.grams)||0)} جم</small></span><b>${num(Number(x.kcal)||0)} سعر</b></div>`).join(''):'<p class="muted">مفيش أكل متسجل في اليوم ده.</p>';
  return `<article class="panel history-day"><button type="button" class="history-day-toggle" data-toggle-history="${safe(date)}" aria-expanded="false"><span class="history-date-title">📅 ${safe(prettyDate(date))}</span><span>🔥 ${num(kcal)} سعر <span class="history-chevron">⌄</span></span></button><div class="history-day-content hidden" id="history-content-${safe(date)}"><div class="history-metrics"><div><small>🔥 السعرات</small><b>${num(kcal)} سعرة</b></div><div><small>🥚 البروتين</small><b>${num(protein,1)} جم</b></div><div><small>💧 المياه</small><b>${num(water)} مل</b></div><div><small>🌙 النوم</small><b>${sleep?num(sleep,1)+' ساعة':'—'}</b></div></div><div class="history-day-food"><h4>🍽️ الأكل المسجل في اليوم</h4>${foods}</div><div class="history-day-actions"><button type="button" class="secondary compact danger-action" data-delete-history-day="${safe(date)}">حذف اليوم بالكامل</button></div></div></article>`;
 }).join('');
 host.querySelectorAll('[data-toggle-history]').forEach(b=>b.onclick=()=>{const box=$('history-content-'+b.dataset.toggleHistory);if(!box)return;box.classList.toggle('hidden');b.setAttribute('aria-expanded',String(!box.classList.contains('hidden')))});
 host.querySelectorAll('[data-delete-history-day]').forEach(b=>b.onclick=()=>{const date=b.dataset.deleteHistoryDay;if(!confirm(`متأكد إنك عايز تحذف كل تسجيلات يوم ${prettyDate(date)} من حسابك؟`))return;db.logs=db.logs.filter(x=>!(x.who===current&&x.date===date&&['food','water','sleep'].includes(x.type)));save();renderAll();showFoodToast('تم حذف تسجيلات اليوم')});
}
// Activity page launcher: keep each exercise type on its own focused screen.
if(!window.__fitbrosActivityLauncherBound){window.__fitbrosActivityLauncherBound=true;document.addEventListener('click',e=>{const btn=e.target.closest('[data-activity-panel]');if(!btn)return;const id=btn.dataset.activityPanel;document.querySelectorAll('.activity-subsection').forEach(el=>el.classList.toggle('hidden',el.id!==id));document.querySelectorAll('.activity-launch').forEach(el=>{const active=el===btn;el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active));});if(id==='gpsSection'){setTimeout(()=>{window.dispatchEvent(new Event('resize'));if(window.gpsMap&&typeof window.gpsMap.invalidateSize==='function')window.gpsMap.invalidateSize();},100);}const section=document.getElementById(id);if(section){const topbar=document.querySelector('#app .topbar');const offset=(topbar?.getBoundingClientRect().height||0)+10;const y=section.getBoundingClientRect().top+window.scrollY-offset;window.scrollTo({top:Math.max(0,y),behavior:'smooth'});}});}

function renderAll(){renderDailyHistory();let w=ownLogs(current,'water').filter(x=>x.date===today()).reduce((s,x)=>s+(Number(x.ml)||0),0);$('myRunTotal').textContent=num(sumRun(current),2)+' كم';$('myWorkoutTotal').textContent=ownLogs(current).filter(x=>['run','exercise','workout','walk'].includes(x.type)).length+' تمرين';renderNeeds();renderList('foodLog',ownLogs(current,'food').filter(x=>x.who===current),x=>`<b>${x.kcal} سعر</b><br><small>${x.grams} جم · بروتين ${x.protein}جم · دهون ${x.fat}جم</small>`);let acts=db.logs.filter(x=>['run','exercise','workout','walk'].includes(x.type));if(activityFilter!=='all')acts=acts.filter(x=>x.type===activityFilter);renderList('activityLog',acts.filter(x=>x.who===current),x=>x.type==='run'?`<b>${num(x.km,2)} كم</b><br><small>${x.min||'—'} دقيقة · بيس ${num(x.pace||((+x.min||0)/(+x.km||1)),2)} دقيقة/كم</small>${x.trackPoints?gpsMiniRoute(x.trackPoints):''}`:x.type==='walk'?`<b>🚶 مشي</b><br><small>${x.steps?num(x.steps)+' خطوة · ':''}${num(x.km,2)} كم · ${num(x.min)} دقيقة</small>${x.trackPoints?gpsMiniRoute(x.trackPoints):''}`:x.type==='workout'?`<b>${x.title}</b><br><small>${x.sets} مجموعات × ${x.reps||'—'} عدة${x.seconds?' · '+x.seconds+' ثانية':''}${x.weightKg?' · وزن '+x.weightKg+' كجم':''} · ${x.muscleName||MUSCLES[x.muscle]||''}</small>`:`<b>${x.min} دقيقة</b>`);renderList('activityHistoryLog',acts.filter(x=>x.who===current),x=>x.type==='run'?`<b>${num(x.km,2)} كم</b><br><small>${x.min||'—'} دقيقة · بيس ${num(x.pace||((+x.min||0)/(+x.km||1)),2)} دقيقة/كم</small>${x.trackPoints?gpsMiniRoute(x.trackPoints):''}`:x.type==='walk'?`<b>🚶 مشي</b><br><small>${x.steps?num(x.steps)+' خطوة · ':''}${num(x.km,2)} كم · ${num(x.min)} دقيقة</small>${x.trackPoints?gpsMiniRoute(x.trackPoints):''}`:x.type==='workout'?`<b>${x.title}</b><br><small>${x.sets} مجموعات × ${x.reps||'—'} عدة${x.seconds?' · '+x.seconds+' ثانية':''}${x.weightKg?' · وزن '+x.weightKg+' كجم':''} · ${x.muscleName||MUSCLES[x.muscle]||''}</small>`:`<b>${x.min} دقيقة</b>`);renderList('sleepLog',ownLogs(current,'sleep'),x=>`<b>${x.hours} ساعة</b>`);renderCompare();renderChallenges();renderPlan();renderMuscleRecovery()}
document.querySelectorAll('[data-activity-filter]').forEach(b=>b.onclick=()=>{activityFilter=b.dataset.activityFilter;document.querySelectorAll('[data-activity-filter]').forEach(x=>x.classList.toggle('active',x.dataset.activityFilter===activityFilter));renderAll()});

window.addEventListener('pageshow',()=>{if(!$('app').classList.contains('hidden'))refreshDashboard()});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('app').classList.contains('hidden'))refreshDashboard()});

// Saved route explorer: draws actual recorded GPS points, not illustrative lines.
let savedRoutesMap=null;
function renderSavedRoutes(){
 const mapEl=document.getElementById('savedRoutesMap');if(!mapEl)return;
 const status=document.getElementById('savedRoutesStatus');
 if(!window.L){if(status)status.textContent='تعذر تحميل مكتبة الخريطة. تأكد من اتصال الإنترنت ثم أعد فتح الصفحة.';return;}
 if(!savedRoutesMap){
  savedRoutesMap=L.map(mapEl,{zoomControl:true}).setView([31.2565,32.2841],12);
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(savedRoutesMap);
  savedRoutesMap.on('tileerror',()=>{if(status)status.textContent='تعذر تحميل خلفية الشوارع حاليًا؛ تحقق من الإنترنت. خطوط المسارات تظهر عند توفر نقاط GPS.'});
 }
 // Resize after the hidden training subsection becomes visible.
 [80,250,650].forEach(ms=>setTimeout(()=>{if(savedRoutesMap){savedRoutesMap.invalidateSize(true);}},ms));
 savedRoutesMap.eachLayer(layer=>{if(layer instanceof L.Polyline && !(layer instanceof L.TileLayer))savedRoutesMap.removeLayer(layer)});
 // Merge synced activity logs with local GPS cache, since local cache can survive a delayed sync.
 let localTracks=[];try{localTracks=JSON.parse(localStorage.getItem('fitbros_gps_tracks_v1')||'[]')}catch(e){}
 const all=[...(Array.isArray(db.logs)?db.logs:[]),...(Array.isArray(localTracks)?localTracks:[])];
 const seen=new Set(), entries=[];
 all.forEach(x=>{
  if(!x||!['run','walk','running','walking'].includes(String(x.type||'').toLowerCase()))return;
  const pts=Array.isArray(x.trackPoints)?x.trackPoints:(Array.isArray(x.points)?x.points:[]);
  const coords=pts.map(p=>({lat:Number(p.lat),lon:Number(p.lon??p.lng)})).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&Math.abs(p.lat)<=90&&Math.abs(p.lon)<=180);
  if(coords.length<2)return;
  const key=String(x.id||x.createdAt||'')+'|'+String(x.who||x.user||'')+'|'+String(x.date||'')+'|'+coords.length;
  if(seen.has(key))return;seen.add(key);
  entries.push({...x,trackPoints:coords,type:['running','run'].includes(String(x.type).toLowerCase())?'run':'walk'});
 });
 const me=String(current??'').trim().toLowerCase();
 const bounds=[];
 entries.forEach(x=>{
  const owner=String(x.who??x.user??x.userId??'').trim().toLowerCase();
  const mine=!!me && owner===me;
  const color=mine?'#ff4545':'#24c875';
  const coords=x.trackPoints.map(p=>[p.lat,p.lon]);
  const line=L.polyline(coords,{color,weight:6,opacity:.96,lineCap:'round',lineJoin:'round'}).addTo(savedRoutesMap);
  const title=String(x.title||(x.type==='run'?'جري GPS':'مشي GPS')).replace(/[<>]/g,'');
  line.bindPopup(`<b>${title}</b><br>${mine?'🔴 مساراتي':'مسار محفوظ'} · ${(Number(x.km)||0).toFixed(2)} كم<br>${String(x.date||'')}`);
  bounds.push(...coords);
 });
 if(status)status.textContent=entries.length?`الخريطة تعرض ${entries.length} مسارًا محفوظًا. الأحمر: مساراتك · الأخضر: مسارات أخرى.`:'لا توجد مسارات GPS محفوظة بنقاط كافية حتى الآن. ابدأ التسجيل من زر GPS واحفظ النشاط ليظهر هنا.';
 const list=document.getElementById('savedRoutesList');
 if(list)list.innerHTML=entries.slice().sort((a,b)=>(Number(b.createdAt)||0)-(Number(a.createdAt)||0)).map(x=>{
  const owner=String(x.who??x.user??x.userId??'').trim().toLowerCase(),mine=!!me&&owner===me;
  return `<div class="saved-route-item"><strong>${String(x.title||(x.type==='run'?'جري GPS':'مشي GPS')).replace(/[<>]/g,'')}</strong><small>${mine?'🔴 مساراتي':'مسار محفوظ'} · ${(Number(x.km)||0).toFixed(2)} كم · ${x.min||'—'} دقيقة · ${String(x.date||'')}</small></div>`;
 }).join('');
 if(bounds.length){try{savedRoutesMap.fitBounds(L.latLngBounds(bounds).pad(.12),{maxZoom:16})}catch(e){}}
}

// GPS and saved routes stay inside the existing Training tab; no separate bottom-navigation page.

window.fitbrosShowActivityPanel = function(id, btn){
  const section=document.getElementById(id);
  if(!section || !section.classList.contains('activity-subsection')) return;
  document.querySelectorAll('.activity-subsection').forEach(el=>el.classList.toggle('hidden',el.id!==id));
  document.querySelectorAll('.activity-launch').forEach(el=>{
    const active=el===btn || el.dataset.activityPanel===id;
    el.classList.toggle('active',active);
    el.setAttribute('aria-selected',String(active));
  });
  if(id==='routesSection') {setTimeout(renderSavedRoutes,120);}
  if(id==='gpsSection') {setTimeout(()=>{
    window.dispatchEvent(new Event('resize'));
    if(gps.map && typeof gps.map.invalidateSize==='function') gps.map.invalidateSize(true);
  },120);}
  requestAnimationFrame(()=>{
    const topbar=document.querySelector('#app .topbar');
    const offset=(topbar?.getBoundingClientRect().height||0)+10;
    const y=section.getBoundingClientRect().top+window.scrollY-offset;
    window.scrollTo({top:Math.max(0,y),behavior:'smooth'});
  });
};
